function createPingHandler(deps) {
  const { clock } = deps;
  return Object.freeze({
    method: 'GET',
    path: '/ping',
    handle(req) {
      return { status: 200, body: { pong: true, at: clock.now() } };
    },
  });
}

module.exports = { createPingHandler };

