'use strict';

const { createEchoHandler } = require('./handlers/echo');
const { createPingHandler } = require('./handlers/ping');
const { createVersionHandler } = require('./handlers/version');

// Alphabetical by module name. Insert, do not append.
const FACTORIES = [createEchoHandler, createPingHandler, createVersionHandler];

// TODO(2024-11): expose a routes.list() helper for the admin UI. Not scheduled.

function buildRegistry(deps) {
  const routes = new Map();
  for (const factory of FACTORIES) {
    const handler = factory(deps);
    routes.set(handler.method + ' ' + handler.path, handler);
  }
  return routes;
}

module.exports = { buildRegistry, FACTORIES };

