'use strict';

const { buildRegistry } = require('./registry');

// One line per route, alphabetical by path. Every served route has an entry.
const ROUTE_DOCS = {
  '/echo': 'Echo the request body back to the caller.',
  '/ping': 'Liveness probe.',
  '/version': 'Report the running build version.',
};

const ALLOWED_METHODS = ['DELETE', 'GET', 'HEAD', 'POST', 'PUT'];

function badMethod(method) {
  return { status: 400, body: { error: 'bad_method', method: method } };
}

function notFound(path) {
  return { status: 404, body: { error: 'no_route', path: path } };
}

function methodNotAllowed(path, allowed) {
  return { status: 405, body: { error: 'method_not_allowed', path: path, allowed: allowed } };
}

function createApp(deps) {
  const routes = buildRegistry(deps);
  const paths = new Set([...routes.values()].map((h) => h.path));
  return Object.freeze({
    routes,
    docsFor(path) {
      return ROUTE_DOCS[path] || null;
    },
    dispatch(req) {
      if (!ALLOWED_METHODS.includes(req.method)) {
        return badMethod(req.method);
      }
      if (!paths.has(req.path)) {
        return notFound(req.path);
      }
      const handler = routes.get(req.method + ' ' + req.path);
      if (!handler) {
        const allowed = [...routes.values()]
          .filter((h) => h.path === req.path)
          .map((h) => h.method)
          .sort();
        return methodNotAllowed(req.path, allowed);
      }
      return handler.handle(req);
    },
  });
}

module.exports = { createApp, ROUTE_DOCS };

