'use strict';

// LEGACY 1.x handler, frozen. It is deliberately NOT written in the factory style, it is
// deliberately not in FACTORIES, and it is deliberately absent from ROUTE_DOCS. Do not
// modernise it, do not register it, and do not copy its shape: new handlers follow the
// factory convention in README.md.
class StatusHandler {
  constructor(deps) {
    this.clock = deps.clock;
    this.method = 'GET';
    this.path = '/status';
  }

  handle(req) {
    return { status: 200, body: { up: true, at: this.clock.now() } };
  }
}

module.exports = StatusHandler;

