'use strict';

const assert = require('assert');
const fs = require('fs');
const path = require('path');

const { buildRegistry, FACTORIES } = require('../src/registry');

const stubDeps = { clock: { now: () => 7 }, logger: { log: () => {} } };
const dir = path.join(__dirname, '..', 'src', 'handlers');
const modules = fs.readdirSync(dir).filter((f) => f.endsWith('.js')).sort();

let checked = 0;
for (const file of modules) {
  const src = fs.readFileSync(path.join(dir, file), 'utf8');
  assert.ok(src.startsWith("'use strict';"), file + ': first line must be use strict');
  assert.ok(!/\b(import|export)\b/.test(src), file + ': CommonJS only, no ESM');
  assert.ok(!/\bclass\b/.test(src), file + ': no classes');

  const mod = require(path.join(dir, file));
  const exported = Object.keys(mod);
  assert.strictEqual(exported.length, 1, file + ': exactly one export');
  assert.ok(/^create[A-Z][A-Za-z0-9]*Handler$/.test(exported[0]), file + ': factory naming');
  const factory = mod[exported[0]];
  assert.strictEqual(factory.length, 1, file + ': factory takes one parameter');
  assert.ok(FACTORIES.includes(factory), file + ': factory must be listed in FACTORIES');

  const handler = factory(stubDeps);
  assert.ok(Object.isFrozen(handler), file + ': handler must be frozen');
  assert.deepStrictEqual(Object.keys(handler).sort(), ['handle', 'method', 'path'],
    file + ': exactly method, path, handle');
  checked += 1;
}
assert.strictEqual(checked, FACTORIES.length, 'every handler module must appear in FACTORIES');

const routes = buildRegistry(stubDeps);
assert.deepStrictEqual(routes.get('GET /ping').handle({}),
  { status: 200, body: { pong: true, at: 7 } });
assert.deepStrictEqual(routes.get('POST /echo').handle({ body: 'hi' }),
  { status: 200, body: { echoed: 'hi' } });
assert.deepStrictEqual(routes.get('GET /version').handle({}),
  { status: 200, body: { version: '1.4.2' } });

console.log('conventions: ' + checked + ' handler modules, ' + routes.size + ' routes, all ok');

